import RNA, random, time, multiprocessing as mp

target = "((((....).))).((((....).))).((((....).))).((((....).))).((((....).))).((((....).))).((((((((((((((((((((((...)))).))))))).(((((..((((((((((..(((((((...))))))).))))))))))((((.((((((...)))))))))))))))...))))))))))).((((....).))).((((....).))).((((....).))).((((....).))).((((....).)))"
n=len(target)
stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

paired=set(pairs.keys())
WC={'A':'U','U':'A','G':'C','C':'G','G':'U','U':'G'}

def make_init(seed):
    random.seed(seed)
    seq=['A']*n
    pairlist=[(i,j) for i,j in pairs.items() if i<j]
    used=set(); stems=[]
    for i,j in pairlist:
        if i in used: continue
        stem=[(i,j)]; k=1
        while (i+k,j-k) in pairs and (i+k)<(j-k):
            stem.append((i+k,j-k)); k+=1
        for a,b in stem: used.add(a); used.add(b)
        stems.append(stem)
    for stem in stems:
        ci,cj=stem[0]
        seq[ci]='G'; seq[cj]='C'
        for (a,b) in stem[1:]:
            r=random.choice(['GC','CG','AU','UA','GU','UG','GC','CG'])
            seq[a]=r[0]; seq[b]=r[1]
    tetra=[4,18,32,46,60,74,217,231,245,259,273]
    tri=[106,148,180]
    for s in tetra: seq[s]='G';seq[s+1]='A';seq[s+2]='A';seq[s+3]='A'
    for s in tri: seq[s]='G';seq[s+1]='A';seq[s+2]='A'
    return ''.join(seq)

def dist(s):
    return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)

def worker(args):
    seed,steps=args
    random.seed(seed)
    cur=make_init(seed)
    cur_d=dist(cur)
    best,best_d=cur,cur_d
    for _ in range(steps):
        c=list(cur)
        m=random.choice([1,1,1,2,2,3])
        for _ in range(m):
            i=random.randrange(n)
            if i in paired:
                j=pairs[i]
                p=random.choice(['GC','CG','AU','UA','GU','UG','GC','CG','AU'])
                c[i]=p[0]; c[j]=p[1]
            else:
                c[i]=random.choice('ACGU')
        c=''.join(c); d=dist(c)
        if d<cur_d or (d==cur_d and random.random()<0.4):
            cur,cur_d=c,d
            if d<best_d: best,best_d=c,d
    return best_d,best

if __name__=='__main__':
    t0=time.time()
    args=[(s, 8000) for s in range(128)]
    with mp.Pool(64) as p:
        results=p.map(worker, args)
    results.sort()
    print("best", results[0][0])
    print(results[0][1])
    print("elapsed", time.time()-t0)
